        if (typeof obj.temp !== 'undefined' && obj.temp !== '' )                data["temp"] = Number(obj.temp);
        if (typeof obj.humidity !== 'undefined' && obj.humidity !== '' )        data["humidity"] = Number(obj.humidity);

        // Skip adding GPS values if latitude or longitude are 0:
        if (typeof obj.lat !== 'undefined' && Number(obj.lat) !== 0 || typeof obj.lng !== 'undefined' && Number(obj.lng) !== 0) {
            if (typeof obj.lat !== 'undefined' && obj.lat !== '' )                  data["latitude"] = Number(obj.lat);     // tags["latitude"] = obj.lat;
            if (typeof obj.lng !== 'undefined' && obj.lng !== '' )                  data["longitude"] = Number(obj.lng);    // tags["longitude"] = obj.lng;
            if (typeof obj.date !== 'undefined' && obj.date !== '' )                data["gps_date"] = Number(obj.date);
            if (typeof obj.time !== 'undefined' && obj.time !== '' )                data["gps_time"] = Number(obj.time);
            if (typeof obj.speed !== 'undefined' && obj.speed !== '' )              data["speed"] = Number(obj.speed);
            if (typeof obj.satellites !== 'undefined' && obj.satellites !== '' )    data["satellites"] = Number(obj.satellites);
            if (typeof obj.altitude !== 'undefined' && obj.altitude !== '' )        data["altitude"] = Number(obj.altitude);
            if (typeof obj.hdop !== 'undefined' && obj.hdop !== '' )                data["hdop"] = Number(obj.hdop);
            if (typeof obj.course !== 'undefined' && obj.course !== '' )            data["course"] = Number(obj.course);
        }

        if (typeof obj.rssi_STA !== 'undefined' && obj.rssi_STA !== '' ) data["rssi_STA"] = Number(obj.rssi_STA);

        if (typeof obj.vBat !== 'undefined' && obj.vBat !== '' )                data["vBat"] = obj.vBat;
        if (typeof obj.vBus !== 'undefined' && obj.vBus !== '' )                data["vBus"] = obj.vBus;
        if (typeof obj.PowerStatus !== 'undefined' && obj.PowerStatus !== '' )  data["PowerStatus"] = obj.PowerStatus;
        if (typeof obj.ChargingStatus !== 'undefined' && obj.ChargingStatus !== '' ) data["ChargingStatus"] = obj.ChargingStatus;

    } else if (topic == "status") {
        // d [/iot-co2Tracker/12230195/status] {"connected":true}
        var obj = JSON.parse(msg.payload);
        if (typeof obj.connected !== 'undefined' && obj.connected !== '' )  data["connected"] = Boolean(obj.connected);
    } else return null;

    // Update location tags
    if (typeof data["latitude"] !== 'undefined' || typeof data["longitude"] !== 'undefined'){
        tags["latitude"]  = data["latitude"];
        tags["longitude"]  = data["longitude"];
    } else {
        data["latitude"]  = tags["latitude"];
        data["longitude"]  = tags["longitude"];
    }

} else {
