// Code added here will be run once
// whenever the node is started.
context.PrepareDataInfluxDB = function (msg) {

    var data = {
        // IoT-PostBox board:
        vBat: msg.payload_decoded.vBat,
        vBus: msg.payload_decoded.vBus,
        PowerStatus: msg.payload_decoded.powerStatus,
        ChargingStatus: msg.payload_decoded.chargingStatus,

        // CO2 sensor:
        CO2: msg.payload_decoded.co2,
        temp: msg.payload_decoded.temperature,
        humidity: msg.payload_decoded.humidity,

        // GPS sensor:
        latitude: msg.payload_decoded.latitude,
        longitude: msg.payload_decoded.longitude,
        altitude: msg.payload_decoded.altitude,
        speed: msg.payload_decoded.gpsSpeed,
        satellites: msg.payload_decoded.gpsSatellites,
        hdop: msg.payload_decoded.hdop,
        course: msg.payload_decoded.gpsCourse,
        gps_time: msg.payload_decoded.gpsTime,

        // LoRaWAN Metadata:
        rssi: msg.rssi,
        snr: msg.snr,
        consumed_airtime: Number(msg.consumed_airtime.substring(0, msg.consumed_airtime.length - 1)),
        gateway_id: msg.gateway_id
    };

    return data;
}

context.PrepareTagsInfluxDB = function (msg) {

    var tags = {};

    // DeviceId:
    tags["deviceId"] = String(msg.device_id);

    // InfluxDb tags:
    tags["location"] = "Unknown";
    if (msg.payload_decoded.hasOwnProperty("latitude")) tags["latitude"] = msg.payload_decoded.latitude;
    if (msg.payload_decoded.hasOwnProperty("longitude")) tags["longitude"] = msg.payload_decoded.latitude;
    // if (data.hasOwnProperty("latitude") && data.hasOwnProperty("longitude")) 
    //     tags["location"] = geohash.encode(data["latitude"], data["longitude"]);
    tags["source"] = "TTN";


    return tags;
}
